mapper.sql:
with assetHold as (select gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(nvl(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue, gavInfo.portfolioId1 from (select psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId, psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) else (NVL(psv.TDY_FLOAT_INGPL,0)+NVL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, pp.PORTFOLIO_ID portfolioId1 from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND fp.FINPROD_MARKET_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,nvl(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and to_char(ppv.CDATE,'yyyy-mm-dd')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )

with assetHold as (select gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(nvl(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue,gavInfo.portfolioId1 from (select psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId, psv.MARKET_VALUE marketValue,psv.SHARE_AMT shareAmt,psv.DSC_COST_AMT dscCostAmt, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, pp.PORTFOLIO_ID portfolioId1 from PTL_SEC_PIERCE_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID where 1=1
AND fp.FINPROD_MARKET_ID IN
#{item}
and to_char(psv.CDATE,'yyyy-mm-dd') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,nvl(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and to_char(ppv.CDATE,'yyyy-mm-dd')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )

mapper.select:
SELECT FINPROD_MARKET_ID id, nvl(FINPROD_ABBR,FINPROD_NAME) text FROM FIN_PRODUCT WHERE FINPROD_TYPE2 in
#{item}
AND (FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR FINPROD_NAME LIKE CONCAT('%',CONCAT(#{search},'%')) OR FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{search},'%')))
UNION ALL SELECT FINPROD_MARKET_ID id, nvl(FINPROD_ABBR,FINPROD_NAME) text FROM FIN_PRODUCT
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = FIN_PRODUCT.FINPROD_ID AND dani.MODEL_TYPE='02'
AND dani.INSTITUTION_CODE IN
#{item}
WHERE FINPROD_TYPE2 in
#{item}
AND (FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR FINPROD_NAME LIKE CONCAT('%',CONCAT(#{search},'%')) OR FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{search},'%')))

select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, round(sum(nvl(assetHold1.marketValue,0))/sum(assetHold1.tdyAssetValue)*100,2) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo, null belongInstitutionCodeNew from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr union all select null finprodMarketId,null finprodAbbr,assetHold1.portFolioName,assetHold1.marketValue,assetHold1.dscCostAmt,assetHold1.shareAmt, assetHold1.marketValueRatio,assetHold1.portfolioId,'01' as hasChildren ,assetHold1.finprodMarketId parentInfo,assetHold1.portFolioName childInfo, assetHold1.belongInstitutionCode belongInstitutionCodeNew from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1

select.if:
select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, round(sum(nvl(assetHold1.marketValue,0))/sum(assetHold1.tdyAssetValue)*100,2) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo from ( SELECT assetHold.* FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 WHERE NVL(assetHold1.shareAmt,0)!=0 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr

select null finprodMarketId,null finprodAbbr,assetHold1.portFolioName,assetHold1.marketValue,assetHold1.dscCostAmt,NVL(assetHold1.shareAmt,0) shareAmt, assetHold1.marketValueRatio,assetHold1.portfolioId,'01' as hasChildren ,assetHold1.finprodMarketId parentInfo,assetHold1.portFolioName childInfo, assetHold1.belongInstitutionCode belongInstitutionCodeNew from ( SELECT assetHold.*, DATAINST.BELONG_INSTITUTION_CODE belongInstitutionCode FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 where assetHold1.finprodMarketId = #{parentId} AND NVL(assetHold1.shareAmt,0)!=0

select assetHold1.finprodMarketId,assetHold1.finprodAbbr,null portFolioName,sum(assetHold1.marketValue) as marketValue, sum(assetHold1.dscCostAmt) as dscCostAmt,sum(assetHold1.shareAmt) as shareAmt, sum(assetHold1.marketValueRatio) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,assetHold1.finprodMarketId childInfo from ( SELECT assetHold.* FROM assetHold LEFT JOIN DATA_AUTH_NOTIFY_INST DATAINST ON assetHold.portfolioId1 = DATAINST.BUSINESS_ID AND DATAINST.DATA_TYPE='PTL01' AND DATAINST.MODEL_TYPE = '02' WHERE 1=1
AND DATAINST.INSTITUTION_CODE IN
#{item}
) assetHold1 WHERE NVL(assetHold1.shareAmt,0)!=0 group by assetHold1.finprodMarketId,assetHold1.finprodAbbr
